NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'Zechariah'

CHAPTERS = {
    1: {
        1: 'Im achten Monat des zweiten Jahres des Darius geschah das Wort JHWH s zu Sacharja, dem Sohn Berechjas, des Sohns Iddos, dem Propheten {folgendermaßen}:',
        2: 'JHWH zürnt Zorn gegen (über) eure Väter.',
        3: 'Und du sollst zu ihnen sprechen: So spricht JHWH der Heerscharen (Zebaot): Kehrt um zu mir, Ausspruch JHWH s der Heerscharen (Zebaot), und ich kehre um zu euch, spricht JHWH der Heerscharen (Zebaot).',
        4: 'Seid nicht wie eure Väter, denen die ersten (früheren) Propheten zuriefen {folgendermaßen}: So spricht JHWH der Heerscharen (Zebaot): Kehrt doch um von euren bösen (schlechten) Wegen und von euren bösen (schlechten) Taten! Aber sie hörten nicht und merkten nicht auf micht, Ausspruch JHWH s.',
        5: 'Eure Väter, wo [sind] sie? Und die Propheten, leben sie ewig?',
        6: 'Jedoch meine Worte und meine Ziele (Vorhaben), die ich meinen Dienern (Sklaven), den Propheten befahl, erreichten sie eure Väter nicht? Und sie kehrten um und sie sprachen: wie JHWH der Heerscharen (Zebaot) dachte (sann, trachtete) mit uns uns zu handeln (machen, tun) nach (wie) unseren Wege und nach (wie) unseren Handlungen, so tat (handelte, machte) er mit uns.',
        7: 'Am vierundzwandzigsten Tag des elften Monats, welcher ist der Monat Schebat, im zweiten Jahr des Darius geschah das Wort JHWH s zu Sacharja, dem Sohn Berechjas, des Sohns Iddos, dem Propheten {folgendermaßen}:',
        8: 'ich sah nachts (in der Nacht), und siehe, ein Mann reitend auf einem roten Pferd und er blieb stehen zwischen den Myrten, die aus der Tiefe (Talgrund), und hinter ihm [waren] rote, hellrote und weiße Pferde.',
        9: 'Und ich sprach: Was [sind] diese, mein Herr? Und der Engel (Bote), der mit mir redete, sprach zu mir: Ich selbst zeige dir, wer diese [sind].',
        10: 'Und der Mann, der zwischen den Myrten stehen blieb, antwortete und er sprach: Diese [sind es], welche JHWH geschickt (senden) hat, um auf der Erde (Welt, Land) umherzugehen.',
        11: 'Und sie antworteten dem Engel (Boten) JHWH s, der zwischen den Myrten stehen blieb, und sie sprachen: Wir sind auf [der] Erde (Welt, Land) umhergegangen, und siehe: die ganze Erde (Welt, Land) sitzt still (ist bewohnt) und ruht.',
        12: 'Und der Engel (Bote) JHWH s antwortete und sprach: JHWH der Heerscharen (Zebaot), wie lange erbarmst du dich nicht über Jerusalem und über die Städte Judas, welchen du zürnst diese siebzig Jahre.',
        13: 'Und JHWH antwortete dem Engel (Boten), der mit mir redete, Worte des Guten, Worte der (von) Tröstungen.',
        14: 'Und der Engel (Bote), der mit mir redete, sprach zu mir: Rufe (Schreie) {folgendermaßen}: So spricht JHWH der Heerscharen (Zebaot): Ich eifere für Jerusalem und für Zion [mit] großer Leidenschaft.',
        15: 'und [mit] großem Zorn zürne ich über (gegen) die stolzen (sorglosen, übermütigen) Völker, die, [als] ich wenig zürnte, aber haben jenen zur Bosheit (Unheil) geholfen.',
        16: 'Deshalb, so spricht JHWH: Ich bin umgekehrt zu Jerusalem in Erbarmen; mein Haus werde ich darin bauen, Ausspruch JHWH s der Heerscharen (Zebaot), und die Messschnur ausbreiten (erstrecken) über Jerusalem.',
        17: 'Rufe (Schreie) weiter {folgendermaßen}: So spricht JHWH der Heerscharen (Zebaot): Meine Stadt soll doch wieder überfließen von Gutem; und JHWH tröstet [immer] noch Zion, und erwählt [immer] noch {aus} Jerusalem.',
    },
    2: {
        1: 'Und ich erhob (tat auf) meine Augen und ich sah und siehe: vier Hörner.',
        2: 'Und ich sprach zu dem Engel (Boten), der mit mir redete: „Was [sind] diese?“Und er sprach zu mir: „Dies [sind] die Hörner, die Juda, Israel und Jerusalem zerstreut haben.“',
        3: 'Und JHWH ließ mich vier Handwerker (Schmiede, Arbeiter) sehen.',
        4: 'Und ich sprach: „Was wollen diese tun (machen)?“Und er sprach {folgendermaßen}: „Dies [sind] die Hörner, die Juda [so] zerstreut haben, dass kein Mann (niemand) seinen Kopf erhob; und diese kamen um sie zu schrecken (in Schrecken zu versetzen), um niederzuwerfen die Hörner der Völker, die ein Horn zum Land Juda tragen um es zu zerstreuen.“',
        5: 'Und ich erhob (tat auf) meine Augen und sah und siehe: ein Mann und in seiner Hand [war] eine Messschnur.',
        6: 'Und ich sprach zu ihm: „Wohin gehst du?“Und er sprach zu mir: „Jerusalem einzuüben (zu lernen) um zu sehen wie groß seine Breite und wie groß seine Länge [ist].“',
        7: 'Und siehe: ein Engel (Bote), der mit mir redete, ging hinaus. Und ein zweiter Engel (Bote) ging hinaus ihm entgegen.',
        8: 'Und er sprach zu ihm: „Laufe, rede zu diesem Jungen {folgendermaßen}: »Jerusalem soll ein offenes Land bleiben wegen der vielen Menschen und Vieh in seiner Mitte.',
        9: 'Und ich werde für es, Ausspruch JHWH s, eine Feuermauer ringsumher sein und ich werde zur Herrlichkeit in seiner Mitte.',
        10: 'Auf (Wehe), auf (wehe), {und} flieht aus dem Land des Nordens, Ausspruch JHWH s! Denn wie (mit, gemäß) [die] vier Winde des Himmel habe ich euch zerstreut (ausgebreitet), Ausspruch JHWH s.',
        11: 'Auf (Wehe), Zion, entkomme (rette dich), die du [bei der] Tochter Babels wohnst (lebst, sitzt)!',
        12: 'Denn so spricht JHWH Zebaot: Zur (nachdem, nach, mit, dessen) Herrlichkeit (Wichtigkeit) hat (hatte) er mich zu den Völkern gesandt, die euch geplündert hatten (ausplündern, berauben). Denn (ja) wer (diejenigen, die) {in} euch schlägt (anrührt), schlägt (rührt an) {in} seinen [eigenen] Augapfel.',
        13: 'Denn {siehe}, [ich] schüttle (schwinge, erhebe) meine Hand gegen sie, so dass (und) sie eine Beute für ihre Sklaven (Knechte, die ihnen dienen) werden {werden}, damit (so dass, dann, und) ihr erkennen (wissen) werdet, dass JHWH Zebaot mich gesandt hat. Rufe laut aus und freue dich, Tochter Zions, denn {siehe}, ich komme (werde kommen), um (und) in eurer Mitte zu bleiben (wohnen), Ausspruch JHWH s. Dann (und) werden sich viele Völker {zu} JHWH [gemeinsam] anschließen an jenem Tag, und (dann, so dass) sie werden mein Volk sein (werden) und (dann, so dass; aber) ich werde in deiner Mitte wohnen und (dann, so dass) du wirst erkennen (wissen), dass JHWH Zebaot mich zu dir gesandt hat. Dann (und) wird JHWH Juda in Besitz nehmen (erben) [als] seinen Anteil (Erbe, Gebiet, Belohnung) in (auf) dem heiligen Land, und er wird {in} Jerusalem wieder (erneut) erwählen. Pst ([Sei] still), alles Fleisch, vor (in der Gegenwart, vor dem Gesicht) JHWH! Denn er hat sich von seinem heiligen Wohnort aufgemacht (macht sich auf)!«“',
    },
    3: {
        1: 'Und er ließ mich sehen (zeigte mir) Jeschua, den Hohenpriester, der stand vor {dem Angesicht} dem Engel (Bote) JHWH s; und auch {der} Satan stand auf seiner rechten Seite (zu seiner Rechten) um ihn anzuklagen.',
        2: 'Und JHWH sprach zu {dem} Satan: JHWH bedrohe (schelte, schreie dich an) dich, Satan! {Und} JHWH bedrohe (schelte, schreie dich an) dich, der auserwählt hat (erwählt hat) Jerusalem! Ist dieser nicht ein Holzscheit (Brandscheit), das herausgezogen wurde vom Feuer?',
        3: 'Aber Jeschua war bekleidet (angezogen) mit schmutzigen Gewändern (Kleidern); und er stand vor {dem Angesicht} dem Engel (Bote).',
        4: 'Und er antwortete und sprach zu denen, die vor ihm (vor seinem Angesicht) standen {folgendermaßen}: Entfernt (lasst weichen) die schmutzigen Gewänder (Kleider) von ihm! Und er sprach zu ihm: Schau (siehe)! Ich habe weggenommen (hinübergehen lassen, vergeben) von dir deine Sünde und bekleide (ziehe dich an) dich mit Festgewändern (Feierkleidern).',
        5: 'Und ich sprach: Man setze {ihm} einen reinen Kopfbund (Turban) auf seinen Kopf (Haupt)! Und sie setzten den reinen Kopfbund (Turban) auf seinen Kopf (Haupt) und bekleideten ihn mit Gewändern (Kleidern); während auch der Engel (Bote) JHWH s [dabei] stand.',
        6: 'Und der Engel (Bote) JHWH s versicherte (beteuerte, bezeugte) Jeschua {folgendermaßen}:',
        7: 'So spricht JHWH der Heerscharen (Zebaot): Wenn du auf meinen Wegen gehen wirst und wenn du meine Anordnungen ausführen (befolgen, bewahren) wirst, [dann] wirst du sowohl richten (zu seinem Recht verhelfen) mein Haus als auch behüten (schützen, bewachen) meine Vorhöfe und ich werde dir geben Zugang zwischen diesen, die [hier] stehen.',
        8: 'Höre doch, Jeschua, Hoherpriester - du und deine Freunde (Standesgenossen, Gefährten), die vor dir sitzen! Denn Männer des Wunders [sind] diese. Denn siehe, ich lasse meinen Knecht, den Spross kommen!',
        9: 'Denn siehe, der Stein, den ich vor Jeschua gegeben habe: auf einem Stein [sind] sieben Augen. Siehe, ich graviere eine Gravur in (auf) ihn ein, Ausspruch JHWH s der Heerscharen (Zebaot), und ich lasse von der Sünde dieses Landes ab an einem Tag.',
        10: 'An einem Tag, Ausspruch JHWH s der Heerscharen (Zebaot), werdet ihr einander einladen unter einem Weinstock und unter einem Feigenbaum.',
    },
    4: {
        1: 'Und der Engel (Bote), der mit mir redete, kehrte zurück und er weckte mich, wie einen Mann, der aus seinem Schlaf erweckt wurde.',
        2: 'Und er sprach zu mir: Was siehst du? Und ich sprach: Ich sehe und siehe, ein Leuchter ganz aus Gold und seine Schale (Ölgefäß) auf seinem Haupt (Kopf) und seine sieben Lampen auf ihm, sieben und (mal) sieben Schnauzen (Gießgefäße) für die Lampen, die auf seinem Haupt (Kopf) [sind].',
        3: 'Und zwei Ölbäume über ihm, einer zur Rechten der Schale (Ölgefäß) und einer an seiner Linken.',
        4: 'Und ich antwortete und sprach zu dem Engel (Bote), der mit mir redete, {folgendermaßen}: Was [sind] diese, mein Herr?',
        5: 'Und der Engel (Bote), der mit mir redete, antwortete und er sprach zu mir: Hast du nicht erkannt (Weißt du nicht), was diese [sind]? Und ich sprach: Nein, mein Herr.',
        6: 'Und er antwortete und er sprach zu mir {folgendermaßen}: Dies ist das Wort JHWH s an Serubbabel {folgendermaßen}: Nicht durch {ein} Heer und nicht durch Kraft, sondern durch meinen Geist, spricht JHWH Zebaot.',
        7: 'Wer bist du, großer Berg? Vor Serubbabel [wirst du] zur Ebene. Und er bringt hervor den Schlussstein, [unter] Zuruf (Lärm, Geschrei): Gnade, Gnade für ihn!',
        8: 'Und das Wort JHWH s geschah zu mir {folgendermaßen}:',
        9: 'Die Hände Serubbabels haben dieses Haus gegründet und seine Hände werden [es] vollenden und du wirst erkennen, dass JHWH Zebaot mich zu euch gesandt hat.',
        10: 'Denn wer verachtet den Tag der Kleinen (Kleinigkeiten)? Und sie werden sich freuen und den Stein des Bleilots (Senkblei) sehen in der Hand Serubbabels. Diese sieben [sind] die Augen JHWH s - jene schweifen auf der ganzen Erde (Land) umher.',
        11: 'Und ich antwortete und sprach zu ihm: Was [sind] diese zwei Ölbäume auf der Rechten des Leuchters und auf seiner Linken?',
        12: 'Und ich antwortete zum zweiten Mal und ich sprach zu ihm: Was [sind] die zwei Ähren (Zweigspitzen) der Ölbäume, die in der Hand der zwei goldenen Röhren [sind], die das Gold aus ihnen gießen?',
        13: 'Und er sprach zu mir: Erkennst du nicht, was diese [sind]? Und ich sprach: Nein, mein Herr.',
        14: 'Und er sprach: Diese zwei [sind] die Söhne des Öls, die beim Herrn der ganzen Erde (Land) stehen.',
    },
    6: {
        1: 'Und ich kehrte um (kehrte zurück, wendete mich) und ich erhob (tat auf) meine Augen und ich sah und siehe: vier Wagen, die herausfuhren (hinausgingen) zwischen zwei Bergen und die Berge der Schlangenberge.',
        2: 'Am ersten Wagen [waren] rote Pferde und am zweiten Wagen [waren] schwarze Pferde.',
        3: 'Und am dritten Wagen [waren] weiße Pferde und am vierten Wagen [waren] gefleckte (scheckige), starke (kräftige) Pferde.',
        4: 'Und ich antwortete und sprach zu dem Engel (Boten), der mit mir redete: Was [sind] diese, mein Herr?',
        5: 'Der Engel (Bote) antwortete und sprach zu mir: Diese [sind die] vier Winde des Himmels, die ausgehen und stehen (hintreten) vor dem Herrn der ganzen Erde (Land),',
        6: 'die auf ihr, und die schwarzen Pferde laufen hinaus zum Land des Nordens und die weißen laufen hinaus hinter ihnen her und die gefleckten (scheckigen) laufen hinaus zum Land des Südens',
        7: 'und die starken (kräftigen) laufen hinaus; und sie wollten umhergehen (umherlaufen) auf dem Land (Erde). Und er sprach: Geht, geht umher auf dem Land (Erde)! Und sie gingen auf dem Land (Erde) umher.',
        8: 'Und er rief mir zu (schrie mich an) und er redete zu mir {folgendermaßen}: Sieh, die, welche hinaus liefen zum Land des Nordens, lassen meinen Geist ruhen (verschaffen... Ruhe, machen... zufrieden) im Land des Nordens.',
        9: 'Und das Wort JHWH s geschah zu mir {folgendermaßen}:',
        10: 'Nimm von den Exulanten (Weggeführten), von Heldai und von Tobija und von Jedaja und gehe du an jenem Tag und gehe [zum] Haus Joschijas, des Sohnes Zefanjas, die aus Babel kamen.',
        11: 'Und nimm Silber und Gold und mache Kronen und setze [sie] auf den Kopf (Haupt) Jeschuas, des Sohnes Jozadaks, dem Hohenpriester.',
        12: 'Und sage (sprich) zu ihm {folgendermaßen}: So spricht JHWH Zebaot: Siehe, ein Mann, Spross [ist] sein Name; unter ihm aber wird [es] hervorsprossen und er wird den Tempel JHWH s bauen.',
        13: 'Und jener wird den Tempel JHWH s bauen und jener wird Hoheit (Majestät, Glanz, Pracht) tragen und er wird sitzen und herrschen auf seinem Thron, auch (und) wird ein Priester auf seinem Thron sein und [der] Rat (Ermahnung, Entschluss, Plan) des Friedens wird zwischen ihnen beiden sein.',
        14: 'Und die Kronen sind (sollen sein) der Heldai und dem Tobija und dem Jedaja und der Gnade des Sohnes Zefanjas zum Andenken (Gedenken, Erinnerung) im Tempel JHWH s.',
        15: 'Und Ferne werden kommen und den Tempel JHWH s bauen und ihr werdet erkennen, dass JHWH Zebaot mich zu euch gesandt hat; und es wird geschehen, wenn ihr ganz gewiss hört auf die Stimme (Ruf) JHWH s, eures Gottes.',
    },
}
